import dev.zomboid.tacz.ScopeZoom;
public class Checks {static int n;static void check(boolean b){if(!b)throw new AssertionError(n);n++;}static double ratio(double a,double b){return Math.tan(Math.toRadians(a)/2)/Math.tan(Math.toRadians(b)/2);}public static void main(String[] args){for(double base:new double[]{60,70,90,110})for(double zoom:new double[]{1,4,8,25}){double f=ScopeZoom.fov(base,zoom,1);check(Math.abs(ratio(base,f)-zoom)<1e-9);check(ScopeZoom.fov(base,zoom,0)==base||Math.abs(ScopeZoom.fov(base,zoom,0)-base)<1e-9);check(Math.abs(ScopeZoom.fov(base,zoom,2)-f)<1e-9);check(ScopeZoom.fov(base,zoom,.5)>=f);}check(ScopeZoom.fov(70,Double.NaN,1)==70);check(ScopeZoom.fov(70,4,-1)==70);check(ScopeZoom.fov(0,4,1)==0);System.out.println("Scope magnification checks: "+n);}}
